insert into public.exercises (key, name, name_i18n, category, equipment, muscles, secondary_muscles, steps, steps_i18n, benefits_i18n)
values
  ('barbell_back_squat', 'Barbell Squat', '{"tr":"Barbell Squat","en":"Barbell Back Squat"}'::jsonb, 'legs', 'barbell', array['quads', 'glutes']::text[], array['hamstrings', 'adductors', 'lower_back', 'abs']::text[], array['Barı omuzların arkasına, trapez üzerine yerleştir; ayaklar omuz genişliğinde.', 'Göğsü dik tutup kalçayı geriye iterek çömel.', 'Dizler ayak uçlarıyla aynı yönü göstersin; uyluklar en az yere paralel olsun.', 'Topuklardan iterek başlangıç pozisyonuna kalk.']::text[], '{"tr":["Barı omuzların arkasına, trapez üzerine yerleştir; ayaklar omuz genişliğinde.","Göğsü dik tutup kalçayı geriye iterek çömel.","Dizler ayak uçlarıyla aynı yönü göstersin; uyluklar en az yere paralel olsun.","Topuklardan iterek başlangıç pozisyonuna kalk."],"en":["Rest the bar on your upper back; feet shoulder-width apart.","Keep your chest up and sit back with your hips.","Keep knees tracking over your toes; go to at least parallel.","Drive through your heels to stand back up."]}'::jsonb, '{"tr":"Alt vücut kuvvetini ve kas kütlesini geliştirir; günlük hareketlerde (oturma, kalkma) güç sağlar.","en":"Builds lower-body strength and muscle; carries over to everyday movements like sitting and standing."}'::jsonb),
  ('goblet_squat', 'Goblet Squat', '{"tr":"Goblet Squat","en":"Goblet Squat"}'::jsonb, 'legs', 'dumbbell', array['quads', 'glutes']::text[], array['abs', 'adductors']::text[], array['Dambılı ya da kettlebell''i göğüs hizasında iki elle tut.', 'Ayaklar omuz genişliğinde, parmak uçları hafif dışa dönük.', 'Dirsekler dizlerin içinden geçecek şekilde derin çömel.', 'Göğsü dik tutarak yukarı kalk.']::text[], '{"tr":["Dambılı ya da kettlebell''i göğüs hizasında iki elle tut.","Ayaklar omuz genişliğinde, parmak uçları hafif dışa dönük.","Dirsekler dizlerin içinden geçecek şekilde derin çömel.","Göğsü dik tutarak yukarı kalk."],"en":["Hold a dumbbell or kettlebell at chest height with both hands.","Feet shoulder-width apart, toes slightly out.","Squat deep so your elbows pass inside your knees.","Stand up keeping your chest tall."]}'::jsonb, '{"tr":"Squat tekniğini öğrenmek için güvenli bir başlangıç; gövde dengesini geliştirir.","en":"A safe way to learn the squat pattern; improves trunk control."}'::jsonb),
  ('front_squat', 'Front Squat', '{"tr":"Front Squat","en":"Front Squat"}'::jsonb, 'legs', 'barbell', array['quads']::text[], array['glutes', 'abs', 'upper_back']::text[], array['Barı omuzların önüne, köprücük kemiklerine yasla; dirsekler yukarıda.', 'Gövde dik, çömelmeye başla.', 'Dirsekleri düşürmeden derine in.', 'Ayak ortasından iterek kalk.']::text[], '{"tr":["Barı omuzların önüne, köprücük kemiklerine yasla; dirsekler yukarıda.","Gövde dik, çömelmeye başla.","Dirsekleri düşürmeden derine in.","Ayak ortasından iterek kalk."],"en":["Rest the bar on the front of your shoulders; elbows high.","Keep your torso upright as you descend.","Go deep without letting your elbows drop.","Push through mid-foot to stand."]}'::jsonb, '{"tr":"Ön bacağı daha çok çalıştırır ve dik gövde duruşu gerektirdiği için core''u güçlendirir.","en":"Emphasizes the quads and builds core strength through an upright torso."}'::jsonb),
  ('bulgarian_split_squat', 'Bulgar Split Squat', '{"tr":"Bulgar Split Squat","en":"Bulgarian Split Squat"}'::jsonb, 'legs', 'dumbbell', array['quads', 'glutes']::text[], array['hamstrings', 'adductors']::text[], array['Arka ayağın üstünü bir sehpaya koy, öndeki ayak bir adım önde.', 'Gövde dik, arka diz yere yaklaşana kadar in.', 'Ön diz ayak ucu yönünde kalsın.', 'Ön ayak topuğundan iterek kalk; setin sonunda bacak değiştir.']::text[], '{"tr":["Arka ayağın üstünü bir sehpaya koy, öndeki ayak bir adım önde.","Gövde dik, arka diz yere yaklaşana kadar in.","Ön diz ayak ucu yönünde kalsın.","Ön ayak topuğundan iterek kalk; setin sonunda bacak değiştir."],"en":["Place the top of your rear foot on a bench; front foot a stride ahead.","Lower until your back knee nearly touches the floor.","Keep the front knee in line with your toes.","Drive through the front heel; switch legs after the set."]}'::jsonb, '{"tr":"Tek bacak kuvvetini ve dengeyi geliştirir; iki bacak arasındaki farkları azaltır.","en":"Builds single-leg strength and balance; reduces side-to-side imbalances."}'::jsonb),
  ('walking_lunge', 'Yürüyen Lunge', '{"tr":"Yürüyen Lunge","en":"Walking Lunge"}'::jsonb, 'legs', 'dumbbell', array['quads', 'glutes']::text[], array['hamstrings', 'calves']::text[], array['Dambılları yanlarda tut, dik dur.', 'Uzun bir adım at ve iki dizi de yaklaşık 90 dereceye bük.', 'Ön topuktan iterek arka bacağı öne getir.', 'Diğer bacakla devam et.']::text[], '{"tr":["Dambılları yanlarda tut, dik dur.","Uzun bir adım at ve iki dizi de yaklaşık 90 dereceye bük.","Ön topuktan iterek arka bacağı öne getir.","Diğer bacakla devam et."],"en":["Hold dumbbells at your sides and stand tall.","Take a long step and bend both knees to about 90 degrees.","Push through the front heel and bring the back leg forward.","Continue with the other leg."]}'::jsonb, '{"tr":"Bacak kuvveti, denge ve koordinasyonu birlikte geliştirir.","en":"Develops leg strength, balance and coordination together."}'::jsonb),
  ('leg_press', 'Leg Press', '{"tr":"Leg Press","en":"Leg Press"}'::jsonb, 'legs', 'machine', array['quads', 'glutes']::text[], array['hamstrings', 'adductors']::text[], array['Sırtını ve kalçanı mindere tam yasla; ayaklar platformda omuz genişliğinde.', 'Kilidi aç ve dizleri göğse doğru kontrollü bük.', 'Kalça minderden kalkmadan en alt noktada dur.', 'Dizleri tam kilitlemeden platformu it.']::text[], '{"tr":["Sırtını ve kalçanı mindere tam yasla; ayaklar platformda omuz genişliğinde.","Kilidi aç ve dizleri göğse doğru kontrollü bük.","Kalça minderden kalkmadan en alt noktada dur.","Dizleri tam kilitlemeden platformu it."],"en":["Keep your back and hips against the pad; feet shoulder-width on the platform.","Release the safety and bend your knees toward your chest under control.","Stop before your hips lift off the pad.","Press the platform without locking your knees."]}'::jsonb, '{"tr":"Belde az yükle bacakları yoğun çalıştırır; yeni başlayanlar için uygundur.","en":"Trains the legs hard with little load on the lower back; beginner friendly."}'::jsonb),
  ('leg_extension', 'Leg Extension', '{"tr":"Leg Extension","en":"Leg Extension"}'::jsonb, 'legs', 'machine', array['quads']::text[], '{}'::text[], array['Diz eklemini makinenin dönme noktasıyla hizala.', 'Bacakları kontrollü şekilde düzleştir.', 'Üstte bir an sık.', 'Yavaşça indir.']::text[], '{"tr":["Diz eklemini makinenin dönme noktasıyla hizala.","Bacakları kontrollü şekilde düzleştir.","Üstte bir an sık.","Yavaşça indir."],"en":["Line up your knee with the machine''s pivot.","Straighten your legs under control.","Squeeze briefly at the top.","Lower slowly."]}'::jsonb, '{"tr":"Ön bacağı izole çalıştırır; ısınma ve rehabilitasyonda kullanılır.","en":"Isolates the quads; useful for warm-ups and rehab."}'::jsonb),
  ('lying_leg_curl', 'Leg Curl', '{"tr":"Leg Curl","en":"Lying Leg Curl"}'::jsonb, 'legs', 'machine', array['hamstrings']::text[], array['calves']::text[], array['Yüzüstü uzan, ped bileklerinin hemen üstünde.', 'Kalçayı minderden kaldırmadan topukları kalçaya doğru çek.', 'Üstte kısa bir duraklama yap.', 'Kontrollü indir.']::text[], '{"tr":["Yüzüstü uzan, ped bileklerinin hemen üstünde.","Kalçayı minderden kaldırmadan topukları kalçaya doğru çek.","Üstte kısa bir duraklama yap.","Kontrollü indir."],"en":["Lie face down with the pad just above your ankles.","Curl your heels toward your glutes without lifting your hips.","Pause briefly at the top.","Lower under control."]}'::jsonb, '{"tr":"Arka bacağı güçlendirir; diz sağlığı ve sprint performansı için önemlidir.","en":"Strengthens the hamstrings; important for knee health and sprinting."}'::jsonb),
  ('romanian_deadlift', 'Romanian Deadlift', '{"tr":"Romanian Deadlift","en":"Romanian Deadlift"}'::jsonb, 'legs', 'barbell', array['hamstrings', 'glutes']::text[], array['lower_back', 'forearms']::text[], array['Barı kalça hizasında tut, dizler hafif bükük.', 'Kalçayı geriye iterek gövdeyi öne eğ; sırt düz.', 'Bar bacaklara yakın, arka bacakta gerilme hissedene kadar in.', 'Kalçayı öne iterek dikleş.']::text[], '{"tr":["Barı kalça hizasında tut, dizler hafif bükük.","Kalçayı geriye iterek gövdeyi öne eğ; sırt düz.","Bar bacaklara yakın, arka bacakta gerilme hissedene kadar in.","Kalçayı öne iterek dikleş."],"en":["Hold the bar at hip height, knees slightly bent.","Push your hips back and hinge forward with a flat back.","Keep the bar close until you feel a hamstring stretch.","Drive your hips forward to stand tall."]}'::jsonb, '{"tr":"Arka zinciri (arka bacak, kalça, bel) güçlendirir; kalça menteşe hareketini öğretir.","en":"Strengthens the posterior chain and teaches the hip hinge."}'::jsonb),
  ('deadlift', 'Deadlift', '{"tr":"Deadlift","en":"Deadlift"}'::jsonb, 'legs', 'barbell', array['glutes', 'hamstrings', 'lower_back']::text[], array['quads', 'upper_back', 'forearms']::text[], array['Bar ayak ortasının üstünde, ayaklar kalça genişliğinde.', 'Eğil, barı omuz genişliğinde tut; sırt düz, göğüs açık.', 'Bacaklarla zemini iterek barı bacaklara yakın kaldır.', 'Üstte kalçayı kilitle, aynı yoldan kontrollü indir.']::text[], '{"tr":["Bar ayak ortasının üstünde, ayaklar kalça genişliğinde.","Eğil, barı omuz genişliğinde tut; sırt düz, göğüs açık.","Bacaklarla zemini iterek barı bacaklara yakın kaldır.","Üstte kalçayı kilitle, aynı yoldan kontrollü indir."],"en":["Bar over mid-foot, feet hip-width apart.","Hinge down and grip just outside your legs; flat back, chest up.","Push the floor away and keep the bar close as you lift.","Lock out your hips, then lower along the same path."]}'::jsonb, '{"tr":"Tüm vücudu çalıştıran temel kuvvet hareketi; tutuş ve duruş gücünü artırır.","en":"A foundational full-body strength lift; builds grip and posture."}'::jsonb),
  ('hip_thrust', 'Hip Thrust', '{"tr":"Hip Thrust","en":"Barbell Hip Thrust"}'::jsonb, 'glutes', 'barbell', array['glutes']::text[], array['hamstrings', 'abs']::text[], array['Sırtının üst kısmını sehpaya yasla, barı kalça kıvrımına koy.', 'Ayaklar yerde, dizler yaklaşık 90 derece.', 'Kalçayı yukarı it; üstte gövde yere paralel.', 'Kalçayı sıkıp kontrollü indir.']::text[], '{"tr":["Sırtının üst kısmını sehpaya yasla, barı kalça kıvrımına koy.","Ayaklar yerde, dizler yaklaşık 90 derece.","Kalçayı yukarı it; üstte gövde yere paralel.","Kalçayı sıkıp kontrollü indir."],"en":["Rest your upper back on a bench with the bar over your hip crease.","Feet flat, knees at about 90 degrees.","Drive your hips up until your torso is parallel to the floor.","Squeeze your glutes, then lower under control."]}'::jsonb, '{"tr":"Kalça kaslarını en etkili çalıştıran hareketlerden; sprint ve sıçrama gücünü destekler.","en":"One of the most effective glute builders; supports sprint and jump power."}'::jsonb),
  ('glute_bridge', 'Kalça Köprüsü', '{"tr":"Kalça Köprüsü","en":"Glute Bridge"}'::jsonb, 'glutes', 'bodyweight', array['glutes']::text[], array['hamstrings', 'abs']::text[], array['Sırtüstü uzan, dizler bükük, ayaklar yerde.', 'Karnı sıkıp kalçayı yukarı kaldır.', 'Omuzdan dizlere düz bir çizgi oluştur.', 'Kısa bir duraklamadan sonra indir.']::text[], '{"tr":["Sırtüstü uzan, dizler bükük, ayaklar yerde.","Karnı sıkıp kalçayı yukarı kaldır.","Omuzdan dizlere düz bir çizgi oluştur.","Kısa bir duraklamadan sonra indir."],"en":["Lie on your back, knees bent, feet flat.","Brace your core and lift your hips.","Form a straight line from shoulders to knees.","Pause briefly, then lower."]}'::jsonb, '{"tr":"Kalçayı aktive eder, bel ağrısına karşı destek olur; ekipmansız yapılır.","en":"Activates the glutes and supports a healthy lower back; no equipment needed."}'::jsonb),
  ('standing_calf_raise', 'Ayakta Kalf Raise', '{"tr":"Ayakta Kalf Raise","en":"Standing Calf Raise"}'::jsonb, 'legs', 'machine', array['calves']::text[], '{}'::text[], array['Ayak uçları basamakta, topuklar boşlukta dur.', 'Topukları olabildiğince yükselt.', 'Üstte bir an bekle.', 'Topukları basamak hizasının altına kadar yavaşça indir.']::text[], '{"tr":["Ayak uçları basamakta, topuklar boşlukta dur.","Topukları olabildiğince yükselt.","Üstte bir an bekle.","Topukları basamak hizasının altına kadar yavaşça indir."],"en":["Stand with the balls of your feet on a step, heels hanging.","Rise up as high as you can.","Hold briefly at the top.","Lower your heels slowly below the step."]}'::jsonb, '{"tr":"Baldırları güçlendirir; yürüme, koşma ve ayak bileği dengesine katkı sağlar.","en":"Strengthens the calves; helps walking, running and ankle stability."}'::jsonb),
  ('barbell_bench_press', 'Bench Press', '{"tr":"Bench Press","en":"Barbell Bench Press"}'::jsonb, 'chest', 'barbell', array['chest']::text[], array['triceps', 'front_delts']::text[], array['Sehpaya uzan, gözler barın altında; kürek kemiklerini sıkıştır.', 'Barı omuzdan biraz geniş tut.', 'Barı göğsün alt kısmına kontrollü indir.', 'Ayakları yere basarak barı yukarı it.']::text[], '{"tr":["Sehpaya uzan, gözler barın altında; kürek kemiklerini sıkıştır.","Barı omuzdan biraz geniş tut.","Barı göğsün alt kısmına kontrollü indir.","Ayakları yere basarak barı yukarı it."],"en":["Lie on the bench with eyes under the bar; pull your shoulder blades together.","Grip slightly wider than shoulder-width.","Lower the bar to your lower chest under control.","Press up while driving your feet into the floor."]}'::jsonb, '{"tr":"Üst vücut itme kuvvetini ve göğüs kaslarını geliştirir.","en":"Builds upper-body pressing strength and chest muscle."}'::jsonb),
  ('incline_dumbbell_press', 'Eğimli Dambıl Press', '{"tr":"Eğimli Dambıl Press","en":"Incline Dumbbell Press"}'::jsonb, 'chest', 'dumbbell', array['upper_chest']::text[], array['front_delts', 'triceps']::text[], array['Sehpayı 30–45 dereceye ayarla, dambılları omuz hizasında tut.', 'Dambılları yukarı ve hafif içe doğru it.', 'Üstte dirsekleri kilitlemeden dur.', 'Göğsün yanlarına kontrollü indir.']::text[], '{"tr":["Sehpayı 30–45 dereceye ayarla, dambılları omuz hizasında tut.","Dambılları yukarı ve hafif içe doğru it.","Üstte dirsekleri kilitlemeden dur.","Göğsün yanlarına kontrollü indir."],"en":["Set the bench to 30–45 degrees and hold dumbbells at shoulder level.","Press up and slightly inward.","Stop just short of locking your elbows.","Lower to the sides of your chest under control."]}'::jsonb, '{"tr":"Göğsün üst kısmını hedefler; dambıllar sayesinde iki taraf eşit çalışır.","en":"Targets the upper chest; dumbbells make each side work equally."}'::jsonb),
  ('dumbbell_bench_press', 'Dambıl Bench Press', '{"tr":"Dambıl Bench Press","en":"Dumbbell Bench Press"}'::jsonb, 'chest', 'dumbbell', array['chest']::text[], array['triceps', 'front_delts']::text[], array['Düz sehpaya uzan, dambılları göğüs hizasında tut.', 'Kürek kemikleri geride, ayaklar yerde.', 'Dambılları yukarı it.', 'Göğüs hizasına kontrollü indir.']::text[], '{"tr":["Düz sehpaya uzan, dambılları göğüs hizasında tut.","Kürek kemikleri geride, ayaklar yerde.","Dambılları yukarı it.","Göğüs hizasına kontrollü indir."],"en":["Lie on a flat bench holding dumbbells at chest level.","Keep shoulder blades back and feet planted.","Press the dumbbells up.","Lower back to chest level under control."]}'::jsonb, '{"tr":"Bar''a göre daha geniş hareket açıklığı ve omuz için daha rahat bir yol sağlar.","en":"Offers a larger range of motion and a more shoulder-friendly path than a barbell."}'::jsonb),
  ('push_up', 'Şınav', '{"tr":"Şınav","en":"Push-up"}'::jsonb, 'chest', 'bodyweight', array['chest']::text[], array['triceps', 'front_delts', 'abs']::text[], array['Eller omuz genişliğinden biraz geniş, vücut baştan topuğa düz.', 'Karnı ve kalçayı sık.', 'Göğüs yere yaklaşana kadar in; dirsekler gövdeye yaklaşık 45 derece.', 'Yerden iterek başlangıca dön.']::text[], '{"tr":["Eller omuz genişliğinden biraz geniş, vücut baştan topuğa düz.","Karnı ve kalçayı sık.","Göğüs yere yaklaşana kadar in; dirsekler gövdeye yaklaşık 45 derece.","Yerden iterek başlangıca dön."],"en":["Hands slightly wider than shoulders; body straight from head to heels.","Brace your abs and glutes.","Lower until your chest is near the floor, elbows about 45 degrees from your body.","Push the floor away to return."]}'::jsonb, '{"tr":"Her yerde yapılabilen itme hareketi; göğüs, kol ve core''u birlikte çalıştırır.","en":"A pressing move you can do anywhere; works chest, arms and core together."}'::jsonb),
  ('cable_fly', 'Kablo Fly', '{"tr":"Kablo Fly","en":"Cable Fly"}'::jsonb, 'chest', 'cable', array['chest']::text[], array['front_delts']::text[], array['Makaraları omuz hizasına ayarla, iki kolu da tut, bir adım öne çık.', 'Dirsekler hafif bükük, kolları yanlara aç.', 'Kolları göğsün önünde birleştir.', 'Kontrollü şekilde aç.']::text[], '{"tr":["Makaraları omuz hizasına ayarla, iki kolu da tut, bir adım öne çık.","Dirsekler hafif bükük, kolları yanlara aç.","Kolları göğsün önünde birleştir.","Kontrollü şekilde aç."],"en":["Set pulleys at shoulder height, hold both handles and step forward.","With a slight elbow bend, open your arms out to the sides.","Bring your hands together in front of your chest.","Open back up under control."]}'::jsonb, '{"tr":"Göğsü izole çalıştırır; hareket boyunca sabit gerilim sağlar.","en":"Isolates the chest with constant tension through the range."}'::jsonb),
  ('dips', 'Dips', '{"tr":"Dips","en":"Dips"}'::jsonb, 'chest', 'bodyweight', array['chest', 'triceps']::text[], array['front_delts']::text[], array['Paralel barlarda kollar düz, vücudu taşı.', 'Gövdeyi hafif öne eğerek dirsekleri bük.', 'Omuzlar dirsek hizasına gelene kadar in.', 'Kolları düzleştirerek yukarı it.']::text[], '{"tr":["Paralel barlarda kollar düz, vücudu taşı.","Gövdeyi hafif öne eğerek dirsekleri bük.","Omuzlar dirsek hizasına gelene kadar in.","Kolları düzleştirerek yukarı it."],"en":["Support yourself on parallel bars with straight arms.","Lean slightly forward and bend your elbows.","Lower until your shoulders reach elbow height.","Press back up to straight arms."]}'::jsonb, '{"tr":"Göğsün alt kısmı ve arka kol için güçlü bir vücut ağırlığı hareketi.","en":"A strong bodyweight move for the lower chest and triceps."}'::jsonb),
  ('pull_up', 'Barfiks', '{"tr":"Barfiks","en":"Pull-up"}'::jsonb, 'back', 'pullup_bar', array['lats']::text[], array['biceps', 'upper_back', 'forearms']::text[], array['Barı avuç içleri öne bakacak şekilde, omuzdan geniş tut.', 'Kürek kemiklerini aşağı çekerek başla.', 'Çene barın üstüne çıkana kadar kendini çek.', 'Kolları tamamen açana kadar kontrollü in.']::text[], '{"tr":["Barı avuç içleri öne bakacak şekilde, omuzdan geniş tut.","Kürek kemiklerini aşağı çekerek başla.","Çene barın üstüne çıkana kadar kendini çek.","Kolları tamamen açana kadar kontrollü in."],"en":["Grip the bar palms forward, wider than shoulders.","Start by pulling your shoulder blades down.","Pull until your chin clears the bar.","Lower under control to full arm extension."]}'::jsonb, '{"tr":"Sırt genişliğini ve üst vücut çekme kuvvetini geliştirir.","en":"Builds back width and upper-body pulling strength."}'::jsonb),
  ('chin_up', 'Ters Tutuş Barfiks', '{"tr":"Ters Tutuş Barfiks","en":"Chin-up"}'::jsonb, 'back', 'pullup_bar', array['lats', 'biceps']::text[], array['upper_back']::text[], array['Barı avuç içleri sana bakacak şekilde omuz genişliğinde tut.', 'Göğsü bara doğru çek.', 'Çene barı geçsin.', 'Kontrollü in.']::text[], '{"tr":["Barı avuç içleri sana bakacak şekilde omuz genişliğinde tut.","Göğsü bara doğru çek.","Çene barı geçsin.","Kontrollü in."],"en":["Grip the bar palms facing you, shoulder-width.","Pull your chest toward the bar.","Get your chin over the bar.","Lower under control."]}'::jsonb, '{"tr":"Sırt ile birlikte ön kolu da güçlü çalıştırır; barfikse göre biraz daha kolaydır.","en":"Works the back and biceps; usually a bit easier than a pull-up."}'::jsonb),
  ('lat_pulldown', 'Lat Pulldown', '{"tr":"Lat Pulldown","en":"Lat Pulldown"}'::jsonb, 'back', 'cable', array['lats']::text[], array['biceps', 'upper_back']::text[], array['Dizleri pedin altına sabitle, barı geniş tut.', 'Göğsü hafif yukarı kaldır, hafif geriye yaslan.', 'Barı göğsün üst kısmına çek.', 'Kolları kontrollü şekilde yukarı bırak.']::text[], '{"tr":["Dizleri pedin altına sabitle, barı geniş tut.","Göğsü hafif yukarı kaldır, hafif geriye yaslan.","Barı göğsün üst kısmına çek.","Kolları kontrollü şekilde yukarı bırak."],"en":["Lock your knees under the pad and take a wide grip.","Lift your chest and lean back slightly.","Pull the bar to your upper chest.","Let your arms return up under control."]}'::jsonb, '{"tr":"Barfiks yapamayanlar için sırt genişliği çalışması; yük ayarlanabilir.","en":"Builds back width for those not yet doing pull-ups; load is adjustable."}'::jsonb),
  ('barbell_row', 'Barbell Row', '{"tr":"Barbell Row","en":"Bent-over Barbell Row"}'::jsonb, 'back', 'barbell', array['upper_back', 'lats']::text[], array['biceps', 'rear_delts', 'lower_back']::text[], array['Kalçadan öne eğil, sırt düz, gövde yaklaşık 45 derece.', 'Barı omuz genişliğinde tut.', 'Barı karnın üst kısmına çek; dirsekler geriye.', 'Kontrollü indir.']::text[], '{"tr":["Kalçadan öne eğil, sırt düz, gövde yaklaşık 45 derece.","Barı omuz genişliğinde tut.","Barı karnın üst kısmına çek; dirsekler geriye.","Kontrollü indir."],"en":["Hinge forward with a flat back, torso about 45 degrees.","Grip the bar shoulder-width.","Row it to your upper stomach, elbows driving back.","Lower under control."]}'::jsonb, '{"tr":"Sırt kalınlığını ve duruşu iyileştirir.","en":"Builds back thickness and improves posture."}'::jsonb),
  ('one_arm_dumbbell_row', 'Tek Kol Dambıl Row', '{"tr":"Tek Kol Dambıl Row","en":"One-arm Dumbbell Row"}'::jsonb, 'back', 'dumbbell', array['lats', 'upper_back']::text[], array['biceps', 'rear_delts']::text[], array['Bir el ve diz sehpada, diğer ayak yerde; sırt düz.', 'Dambılı serbest kolla aşağıda tut.', 'Dirseği kalçaya doğru çekerek dambılı kaldır.', 'Kontrollü indir; setin sonunda taraf değiştir.']::text[], '{"tr":["Bir el ve diz sehpada, diğer ayak yerde; sırt düz.","Dambılı serbest kolla aşağıda tut.","Dirseği kalçaya doğru çekerek dambılı kaldır.","Kontrollü indir; setin sonunda taraf değiştir."],"en":["One hand and knee on a bench, other foot on the floor; flat back.","Hold the dumbbell hanging with the free arm.","Row it by driving your elbow toward your hip.","Lower under control; switch sides after the set."]}'::jsonb, '{"tr":"Her sırt yarısını ayrı çalıştırır; beli destekli olduğu için güvenlidir.","en":"Trains each side of the back separately; supported position keeps the lower back safe."}'::jsonb),
  ('seated_cable_row', 'Oturarak Kablo Row', '{"tr":"Oturarak Kablo Row","en":"Seated Cable Row"}'::jsonb, 'back', 'cable', array['upper_back', 'lats']::text[], array['biceps', 'rear_delts']::text[], array['Otur, ayakları platforma koy, dizler hafif bükük.', 'Gövde dik, tutacağı karnına doğru çek.', 'Kürek kemiklerini birbirine yaklaştır.', 'Kolları kontrollü uzat.']::text[], '{"tr":["Otur, ayakları platforma koy, dizler hafif bükük.","Gövde dik, tutacağı karnına doğru çek.","Kürek kemiklerini birbirine yaklaştır.","Kolları kontrollü uzat."],"en":["Sit with feet on the platform, knees slightly bent.","Keep your torso upright and pull the handle to your stomach.","Squeeze your shoulder blades together.","Extend your arms under control."]}'::jsonb, '{"tr":"Sırt ortasını güçlendirir ve omuzları geriye toplayan duruşu destekler.","en":"Strengthens the mid-back and supports a shoulders-back posture."}'::jsonb),
  ('face_pull', 'Face Pull', '{"tr":"Face Pull","en":"Face Pull"}'::jsonb, 'shoulders', 'cable', array['rear_delts', 'upper_back']::text[], '{}'::text[], array['Halatı yüz hizasındaki makaraya tak, iki ucundan tut.', 'Bir adım geri çekil.', 'Halatı yüzüne doğru çekerken elleri dışa aç.', 'Kontrollü bırak.']::text[], '{"tr":["Halatı yüz hizasındaki makaraya tak, iki ucundan tut.","Bir adım geri çekil.","Halatı yüzüne doğru çekerken elleri dışa aç.","Kontrollü bırak."],"en":["Attach a rope to a pulley at face height and hold both ends.","Step back.","Pull toward your face while spreading your hands apart.","Return under control."]}'::jsonb, '{"tr":"Arka omuz ve üst sırtı güçlendirir; omuz sağlığı ve duruş için faydalıdır.","en":"Strengthens the rear delts and upper back; good for shoulder health and posture."}'::jsonb),
  ('overhead_press', 'Overhead Press', '{"tr":"Overhead Press","en":"Overhead Press"}'::jsonb, 'shoulders', 'barbell', array['front_delts', 'side_delts']::text[], array['triceps', 'upper_chest', 'abs']::text[], array['Ayakta, barı köprücük kemiği hizasında tut.', 'Karnı ve kalçayı sık.', 'Barı başın üstüne düz bir çizgide it.', 'Kontrollü şekilde omuz hizasına indir.']::text[], '{"tr":["Ayakta, barı köprücük kemiği hizasında tut.","Karnı ve kalçayı sık.","Barı başın üstüne düz bir çizgide it.","Kontrollü şekilde omuz hizasına indir."],"en":["Stand holding the bar at collarbone height.","Brace your abs and glutes.","Press the bar straight overhead.","Lower back to shoulder height under control."]}'::jsonb, '{"tr":"Omuz kuvvetini ve gövde dengesini geliştirir.","en":"Builds shoulder strength and full-body stability."}'::jsonb),
  ('seated_dumbbell_press', 'Oturarak Dambıl Omuz Press', '{"tr":"Oturarak Dambıl Omuz Press","en":"Seated Dumbbell Shoulder Press"}'::jsonb, 'shoulders', 'dumbbell', array['front_delts', 'side_delts']::text[], array['triceps']::text[], array['Dik sehpaya otur, dambıllar omuz hizasında.', 'Dambılları başın üstüne it.', 'Üstte dirsekleri kilitlemeden dur.', 'Omuz hizasına kontrollü indir.']::text[], '{"tr":["Dik sehpaya otur, dambıllar omuz hizasında.","Dambılları başın üstüne it.","Üstte dirsekleri kilitlemeden dur.","Omuz hizasına kontrollü indir."],"en":["Sit on an upright bench with dumbbells at shoulder height.","Press them overhead.","Stop just short of locking out.","Lower back to shoulder height."]}'::jsonb, '{"tr":"Omuzları sırt destekli ve dengeli şekilde çalıştırır.","en":"Works the shoulders evenly with back support."}'::jsonb),
  ('lateral_raise', 'Yana Açış', '{"tr":"Yana Açış","en":"Lateral Raise"}'::jsonb, 'shoulders', 'dumbbell', array['side_delts']::text[], '{}'::text[], array['Dambılları yanlarda tut, dirsekler hafif bükük.', 'Kolları omuz hizasına kadar yanlara kaldır.', 'Üstte kısa bekle.', 'Yavaşça indir.']::text[], '{"tr":["Dambılları yanlarda tut, dirsekler hafif bükük.","Kolları omuz hizasına kadar yanlara kaldır.","Üstte kısa bekle.","Yavaşça indir."],"en":["Hold dumbbells at your sides, elbows slightly bent.","Raise your arms out to shoulder height.","Pause briefly.","Lower slowly."]}'::jsonb, '{"tr":"Omzun yan kısmını hedefler; omuzlara genişlik kazandırır.","en":"Targets the side delts for broader-looking shoulders."}'::jsonb),
  ('rear_delt_fly', 'Arka Omuz Açış', '{"tr":"Arka Omuz Açış","en":"Rear Delt Fly"}'::jsonb, 'shoulders', 'dumbbell', array['rear_delts']::text[], array['upper_back']::text[], array['Kalçadan öne eğil, sırt düz, dambıllar aşağıda.', 'Dirsekler hafif bükük, kolları yanlara aç.', 'Kürek kemiklerini sık.', 'Kontrollü indir.']::text[], '{"tr":["Kalçadan öne eğil, sırt düz, dambıllar aşağıda.","Dirsekler hafif bükük, kolları yanlara aç.","Kürek kemiklerini sık.","Kontrollü indir."],"en":["Hinge forward with a flat back, dumbbells hanging.","With soft elbows, open your arms out to the sides.","Squeeze your shoulder blades.","Lower under control."]}'::jsonb, '{"tr":"Arka omzu çalıştırır; omuz dengesini sağlar.","en":"Works the rear delts and balances the shoulders."}'::jsonb),
  ('barbell_curl', 'Barbell Curl', '{"tr":"Barbell Curl","en":"Barbell Curl"}'::jsonb, 'arms', 'barbell', array['biceps']::text[], array['forearms']::text[], array['Barı avuç içleri öne bakacak şekilde omuz genişliğinde tut.', 'Dirsekler gövdenin yanında sabit.', 'Barı omuzlara doğru kaldır.', 'Kontrollü indir.']::text[], '{"tr":["Barı avuç içleri öne bakacak şekilde omuz genişliğinde tut.","Dirsekler gövdenin yanında sabit.","Barı omuzlara doğru kaldır.","Kontrollü indir."],"en":["Hold the bar palms forward, shoulder-width.","Keep your elbows pinned to your sides.","Curl the bar toward your shoulders.","Lower under control."]}'::jsonb, '{"tr":"Ön kol (biceps) kuvvetini ve kütlesini artırır.","en":"Builds biceps strength and size."}'::jsonb),
  ('dumbbell_curl', 'Dambıl Curl', '{"tr":"Dambıl Curl","en":"Dumbbell Curl"}'::jsonb, 'arms', 'dumbbell', array['biceps']::text[], array['forearms']::text[], array['Dambılları yanlarda, avuç içleri öne bakacak şekilde tut.', 'Dirsekleri sabit tutarak dambılları kaldır.', 'Üstte biceps''i sık.', 'Yavaşça indir.']::text[], '{"tr":["Dambılları yanlarda, avuç içleri öne bakacak şekilde tut.","Dirsekleri sabit tutarak dambılları kaldır.","Üstte biceps''i sık.","Yavaşça indir."],"en":["Hold dumbbells at your sides, palms forward.","Curl them up keeping your elbows still.","Squeeze at the top.","Lower slowly."]}'::jsonb, '{"tr":"Her kolu ayrı çalıştırarak dengesizlikleri azaltır.","en":"Trains each arm separately to reduce imbalances."}'::jsonb),
  ('hammer_curl', 'Hammer Curl', '{"tr":"Hammer Curl","en":"Hammer Curl"}'::jsonb, 'arms', 'dumbbell', array['biceps', 'forearms']::text[], '{}'::text[], array['Dambılları avuç içleri birbirine bakacak şekilde tut.', 'Dirsekleri sabit tutarak kaldır.', 'Üstte kısa bekle.', 'Kontrollü indir.']::text[], '{"tr":["Dambılları avuç içleri birbirine bakacak şekilde tut.","Dirsekleri sabit tutarak kaldır.","Üstte kısa bekle.","Kontrollü indir."],"en":["Hold dumbbells with palms facing each other.","Curl up keeping your elbows still.","Pause briefly at the top.","Lower under control."]}'::jsonb, '{"tr":"Ön kol ve kavrama kuvvetini de geliştirir.","en":"Also builds forearm and grip strength."}'::jsonb),
  ('triceps_pushdown', 'Triceps Pushdown', '{"tr":"Triceps Pushdown","en":"Triceps Pushdown"}'::jsonb, 'arms', 'cable', array['triceps']::text[], '{}'::text[], array['Yüksek makaraya bar ya da halat tak, dirsekler gövdenin yanında.', 'Kolları tamamen düzleşene kadar aşağı it.', 'Altta arka kolu sık.', 'Dirsekleri oynatmadan kontrollü bırak.']::text[], '{"tr":["Yüksek makaraya bar ya da halat tak, dirsekler gövdenin yanında.","Kolları tamamen düzleşene kadar aşağı it.","Altta arka kolu sık.","Dirsekleri oynatmadan kontrollü bırak."],"en":["Attach a bar or rope to a high pulley; elbows at your sides.","Push down until your arms are straight.","Squeeze your triceps at the bottom.","Return under control without moving your elbows."]}'::jsonb, '{"tr":"Arka kolu izole çalıştırır; itme hareketlerine destek olur.","en":"Isolates the triceps and supports pressing strength."}'::jsonb),
  ('overhead_triceps_extension', 'Baş Üstü Triceps Extension', '{"tr":"Baş Üstü Triceps Extension","en":"Overhead Triceps Extension"}'::jsonb, 'arms', 'dumbbell', array['triceps']::text[], '{}'::text[], array['Dambılı iki elle başın üstünde tut.', 'Dirsekleri yukarıda sabit tutarak dambılı başın arkasına indir.', 'Kolları düzleştirerek yukarı kaldır.', 'Hareketi kontrollü tekrarla.']::text[], '{"tr":["Dambılı iki elle başın üstünde tut.","Dirsekleri yukarıda sabit tutarak dambılı başın arkasına indir.","Kolları düzleştirerek yukarı kaldır.","Hareketi kontrollü tekrarla."],"en":["Hold one dumbbell overhead with both hands.","Keep elbows pointing up and lower it behind your head.","Extend your arms to lift it back up.","Repeat under control."]}'::jsonb, '{"tr":"Arka kolun uzun başını uzamış pozisyonda çalıştırır.","en":"Works the long head of the triceps in a stretched position."}'::jsonb),
  ('skull_crusher', 'Skull Crusher', '{"tr":"Skull Crusher","en":"Skull Crusher"}'::jsonb, 'arms', 'ez_bar', array['triceps']::text[], '{}'::text[], array['Sehpaya uzan, EZ barı kollar düz şekilde göğsün üstünde tut.', 'Dirsekleri sabit tutarak barı alnın üstüne indir.', 'Kolları düzleştirerek kaldır.', 'Kontrollü tekrarla.']::text[], '{"tr":["Sehpaya uzan, EZ barı kollar düz şekilde göğsün üstünde tut.","Dirsekleri sabit tutarak barı alnın üstüne indir.","Kolları düzleştirerek kaldır.","Kontrollü tekrarla."],"en":["Lie on a bench holding an EZ bar above your chest, arms straight.","Keep your elbows still and lower the bar toward your forehead.","Extend your arms to lift it.","Repeat under control."]}'::jsonb, '{"tr":"Arka kol kütlesi için etkili bir yatay hareket.","en":"An effective lying move for triceps size."}'::jsonb),
  ('plank', 'Plank', '{"tr":"Plank","en":"Plank"}'::jsonb, 'core', 'bodyweight', array['abs']::text[], array['obliques', 'front_delts', 'glutes']::text[], array['Dirsekler omuzların altında, ön kollar yerde.', 'Vücut baştan topuğa düz bir çizgi.', 'Karnı ve kalçayı sık, nefesi tutma.', 'Belirlenen süre boyunca pozisyonu koru.']::text[], '{"tr":["Dirsekler omuzların altında, ön kollar yerde.","Vücut baştan topuğa düz bir çizgi.","Karnı ve kalçayı sık, nefesi tutma.","Belirlenen süre boyunca pozisyonu koru."],"en":["Elbows under shoulders, forearms on the floor.","Body in a straight line from head to heels.","Brace your abs and glutes; keep breathing.","Hold for the set time."]}'::jsonb, '{"tr":"Gövde stabilitesini ve duruşu geliştirir; belin korunmasına yardımcı olur.","en":"Improves trunk stability and posture; helps protect the lower back."}'::jsonb),
  ('side_plank', 'Yan Plank', '{"tr":"Yan Plank","en":"Side Plank"}'::jsonb, 'core', 'bodyweight', array['obliques']::text[], array['abs', 'glutes']::text[], array['Yan yat, dirsek omzun altında.', 'Kalçayı kaldırarak vücudu düz bir çizgi yap.', 'Pozisyonu süre boyunca koru.', 'Diğer tarafa geç.']::text[], '{"tr":["Yan yat, dirsek omzun altında.","Kalçayı kaldırarak vücudu düz bir çizgi yap.","Pozisyonu süre boyunca koru.","Diğer tarafa geç."],"en":["Lie on your side with your elbow under your shoulder.","Lift your hips so your body forms a straight line.","Hold for the set time.","Switch sides."]}'::jsonb, '{"tr":"Yan karın kaslarını ve kalça stabilitesini güçlendirir.","en":"Strengthens the obliques and hip stability."}'::jsonb),
  ('dead_bug', 'Dead Bug', '{"tr":"Dead Bug","en":"Dead Bug"}'::jsonb, 'core', 'bodyweight', array['abs']::text[], array['hip_flexors']::text[], array['Sırtüstü uzan, kollar tavana, dizler 90 derece havada.', 'Beli yere bastır.', 'Karşı kol ve bacağı yavaşça uzat.', 'Başlangıca dön, diğer tarafla tekrarla.']::text[], '{"tr":["Sırtüstü uzan, kollar tavana, dizler 90 derece havada.","Beli yere bastır.","Karşı kol ve bacağı yavaşça uzat.","Başlangıca dön, diğer tarafla tekrarla."],"en":["Lie on your back, arms up, knees bent at 90 degrees in the air.","Press your lower back into the floor.","Slowly extend the opposite arm and leg.","Return and repeat on the other side."]}'::jsonb, '{"tr":"Beli koruyarak derin karın kaslarını çalıştırır; koordinasyonu geliştirir.","en":"Trains the deep abs while protecting the lower back; improves coordination."}'::jsonb),
  ('crunch', 'Mekik', '{"tr":"Mekik","en":"Crunch"}'::jsonb, 'core', 'bodyweight', array['abs']::text[], '{}'::text[], array['Sırtüstü uzan, dizler bükük, eller göğüste ya da şakaklarda.', 'Karnı sıkarak omuzları yerden kaldır.', 'Boynu çekmeden üstte kısa bekle.', 'Kontrollü indir.']::text[], '{"tr":["Sırtüstü uzan, dizler bükük, eller göğüste ya da şakaklarda.","Karnı sıkarak omuzları yerden kaldır.","Boynu çekmeden üstte kısa bekle.","Kontrollü indir."],"en":["Lie on your back, knees bent, hands on chest or temples.","Contract your abs to lift your shoulders off the floor.","Pause without pulling on your neck.","Lower under control."]}'::jsonb, '{"tr":"Karın kaslarını hedefleyen temel hareket.","en":"A basic move that targets the abs."}'::jsonb),
  ('hanging_leg_raise', 'Asılı Bacak Kaldırma', '{"tr":"Asılı Bacak Kaldırma","en":"Hanging Leg Raise"}'::jsonb, 'core', 'pullup_bar', array['abs']::text[], array['hip_flexors', 'forearms']::text[], array['Bara asıl, omuzlar aktif.', 'Sallanmadan bacakları kalça hizasına ya da daha yukarı kaldır.', 'Üstte kısa bekle.', 'Kontrollü indir.']::text[], '{"tr":["Bara asıl, omuzlar aktif.","Sallanmadan bacakları kalça hizasına ya da daha yukarı kaldır.","Üstte kısa bekle.","Kontrollü indir."],"en":["Hang from a bar with active shoulders.","Raise your legs to hip height or higher without swinging.","Pause briefly.","Lower under control."]}'::jsonb, '{"tr":"Alt karın ve kavrama kuvveti için zorlu bir hareket.","en":"A challenging move for the lower abs and grip."}'::jsonb),
  ('russian_twist', 'Russian Twist', '{"tr":"Russian Twist","en":"Russian Twist"}'::jsonb, 'core', 'bodyweight', array['obliques']::text[], array['abs']::text[], array['Otur, dizler bükük, gövdeyi hafif geriye yasla.', 'Ellerini birleştir ya da ağırlık tut.', 'Gövdeyi bir sağa bir sola döndür.', 'Sırtı düz tut.']::text[], '{"tr":["Otur, dizler bükük, gövdeyi hafif geriye yasla.","Ellerini birleştir ya da ağırlık tut.","Gövdeyi bir sağa bir sola döndür.","Sırtı düz tut."],"en":["Sit with knees bent and lean back slightly.","Clasp your hands or hold a weight.","Rotate your torso side to side.","Keep your back straight."]}'::jsonb, '{"tr":"Gövdenin dönme kuvvetini ve yan karın kaslarını geliştirir.","en":"Builds rotational strength and the obliques."}'::jsonb),
  ('mountain_climber', 'Mountain Climber', '{"tr":"Mountain Climber","en":"Mountain Climber"}'::jsonb, 'conditioning', 'bodyweight', array['abs', 'full_body']::text[], array['front_delts', 'hip_flexors']::text[], array['Şınav pozisyonu al, eller omuzların altında.', 'Bir dizi göğse doğru çek.', 'Hızla bacak değiştir.', 'Kalçayı yükseltmeden ritmi koru.']::text[], '{"tr":["Şınav pozisyonu al, eller omuzların altında.","Bir dizi göğse doğru çek.","Hızla bacak değiştir.","Kalçayı yükseltmeden ritmi koru."],"en":["Start in a push-up position, hands under shoulders.","Drive one knee toward your chest.","Switch legs quickly.","Keep the rhythm without lifting your hips."]}'::jsonb, '{"tr":"Kalp atışını yükseltir; core''u ve koordinasyonu çalıştırır.","en":"Raises your heart rate while working the core and coordination."}'::jsonb),
  ('burpee', 'Burpee', '{"tr":"Burpee","en":"Burpee"}'::jsonb, 'conditioning', 'bodyweight', array['full_body']::text[], array['chest', 'quads']::text[], array['Ayakta başla, çömel ve ellerini yere koy.', 'Ayakları geriye atıp şınav pozisyonuna geç.', 'Ayakları ellere doğru getir.', 'Yukarı sıçra.']::text[], '{"tr":["Ayakta başla, çömel ve ellerini yere koy.","Ayakları geriye atıp şınav pozisyonuna geç.","Ayakları ellere doğru getir.","Yukarı sıçra."],"en":["Start standing, squat down and place your hands on the floor.","Jump your feet back to a push-up position.","Jump your feet back toward your hands.","Jump up."]}'::jsonb, '{"tr":"Tüm vücudu çalıştıran yüksek yoğunluklu kondisyon hareketi.","en":"A high-intensity full-body conditioning move."}'::jsonb),
  ('jumping_jack', 'Jumping Jack', '{"tr":"Jumping Jack","en":"Jumping Jack"}'::jsonb, 'conditioning', 'bodyweight', array['full_body']::text[], array['calves']::text[], array['Ayaklar bitişik, kollar yanlarda başla.', 'Sıçrayarak ayakları aç, kolları başın üstüne kaldır.', 'Sıçrayarak başlangıca dön.', 'Ritmi koru.']::text[], '{"tr":["Ayaklar bitişik, kollar yanlarda başla.","Sıçrayarak ayakları aç, kolları başın üstüne kaldır.","Sıçrayarak başlangıca dön.","Ritmi koru."],"en":["Start with feet together and arms at your sides.","Jump your feet out and raise your arms overhead.","Jump back to the start.","Keep a steady rhythm."]}'::jsonb, '{"tr":"Isınma ve kardiyo için basit, etkili bir hareket.","en":"A simple, effective warm-up and cardio move."}'::jsonb),
  ('kettlebell_swing', 'Kettlebell Swing', '{"tr":"Kettlebell Swing","en":"Kettlebell Swing"}'::jsonb, 'conditioning', 'kettlebell', array['glutes', 'hamstrings']::text[], array['lower_back', 'abs', 'forearms']::text[], array['Kettlebell''i iki elle tut, ayaklar omuzdan geniş.', 'Kalçadan menteşe yaparak kettlebell''i bacak arasına salla.', 'Kalçayı güçlü şekilde öne iterek göğüs hizasına savur.', 'Kolları değil kalçayı kullan.']::text[], '{"tr":["Kettlebell''i iki elle tut, ayaklar omuzdan geniş.","Kalçadan menteşe yaparak kettlebell''i bacak arasına salla.","Kalçayı güçlü şekilde öne iterek göğüs hizasına savur.","Kolları değil kalçayı kullan."],"en":["Hold the kettlebell with both hands, feet wider than shoulders.","Hinge and swing it back between your legs.","Snap your hips forward to swing it to chest height.","Power comes from the hips, not the arms."]}'::jsonb, '{"tr":"Kalça patlayıcı gücünü ve kondisyonu birlikte geliştirir.","en":"Builds explosive hip power and conditioning together."}'::jsonb),
  ('box_jump', 'Kutu Sıçrama', '{"tr":"Kutu Sıçrama","en":"Box Jump"}'::jsonb, 'conditioning', 'box', array['quads', 'glutes']::text[], array['calves']::text[], array['Kutunun önünde dur, ayaklar kalça genişliğinde.', 'Kolları savurarak çömel ve sıçra.', 'Kutuya iki ayakla yumuşak in.', 'Kutudan adımlayarak in.']::text[], '{"tr":["Kutunun önünde dur, ayaklar kalça genişliğinde.","Kolları savurarak çömel ve sıçra.","Kutuya iki ayakla yumuşak in.","Kutudan adımlayarak in."],"en":["Stand facing the box, feet hip-width.","Swing your arms, dip and jump.","Land softly on the box with both feet.","Step down."]}'::jsonb, '{"tr":"Bacaklarda patlayıcı gücü ve sıçrama kabiliyetini geliştirir.","en":"Develops explosive leg power and jumping ability."}'::jsonb),
  ('farmers_walk', 'Farmer''s Walk', '{"tr":"Farmer''s Walk","en":"Farmer''s Walk"}'::jsonb, 'conditioning', 'dumbbell', array['forearms', 'upper_back']::text[], array['abs', 'glutes']::text[], array['Her elde ağır bir dambıl ya da kettlebell tut.', 'Dik dur, omuzlar geride.', 'Kısa ve kontrollü adımlarla yürü.', 'Belirlenen mesafe ya da süre boyunca devam et.']::text[], '{"tr":["Her elde ağır bir dambıl ya da kettlebell tut.","Dik dur, omuzlar geride.","Kısa ve kontrollü adımlarla yürü.","Belirlenen mesafe ya da süre boyunca devam et."],"en":["Hold a heavy dumbbell or kettlebell in each hand.","Stand tall with shoulders back.","Walk with short, controlled steps.","Continue for the set distance or time."]}'::jsonb, '{"tr":"Kavrama kuvveti, duruş ve gövde dayanıklılığı kazandırır.","en":"Builds grip strength, posture and trunk endurance."}'::jsonb),
  ('step_up', 'Step Up', '{"tr":"Step Up","en":"Step-up"}'::jsonb, 'legs', 'dumbbell', array['quads', 'glutes']::text[], array['hamstrings', 'calves']::text[], array['Bir ayağını sehpaya koy.', 'Öndeki bacakla iterek sehpaya çık.', 'Kontrollü şekilde in.', 'Setin sonunda bacak değiştir.']::text[], '{"tr":["Bir ayağını sehpaya koy.","Öndeki bacakla iterek sehpaya çık.","Kontrollü şekilde in.","Setin sonunda bacak değiştir."],"en":["Place one foot on a box or bench.","Drive through that leg to step up.","Step down under control.","Switch legs after the set."]}'::jsonb, '{"tr":"Tek bacak kuvveti ve dengesi; merdiven çıkma gibi günlük hareketlere doğrudan katkı.","en":"Single-leg strength and balance that carries over to climbing stairs."}'::jsonb),
  ('bodyweight_squat', 'Vücut Ağırlığı Squat', '{"tr":"Vücut Ağırlığı Squat","en":"Bodyweight Squat"}'::jsonb, 'legs', 'bodyweight', array['quads', 'glutes']::text[], array['hamstrings']::text[], array['Ayaklar omuz genişliğinde, kollar önde.', 'Kalçayı geriye iterek çömel.', 'Topuklar yerde, göğüs dik.', 'Yukarı kalk.']::text[], '{"tr":["Ayaklar omuz genişliğinde, kollar önde.","Kalçayı geriye iterek çömel.","Topuklar yerde, göğüs dik.","Yukarı kalk."],"en":["Feet shoulder-width, arms out in front.","Sit back with your hips.","Keep heels down and chest up.","Stand back up."]}'::jsonb, '{"tr":"Başlangıç seviyesi için bacak kuvveti ve hareketlilik; her yerde yapılır.","en":"Beginner-friendly leg strength and mobility you can do anywhere."}'::jsonb),
  ('inverted_row', 'Ters Row', '{"tr":"Ters Row","en":"Inverted Row"}'::jsonb, 'back', 'bodyweight', array['upper_back', 'lats']::text[], array['biceps', 'rear_delts']::text[], array['Bel hizasındaki bir barın altına uzan, barı tut.', 'Vücut topuklardan omuzlara düz.', 'Göğsü bara doğru çek.', 'Kontrollü in.']::text[], '{"tr":["Bel hizasındaki bir barın altına uzan, barı tut.","Vücut topuklardan omuzlara düz.","Göğsü bara doğru çek.","Kontrollü in."],"en":["Lie under a waist-high bar and grab it.","Keep your body straight from heels to shoulders.","Pull your chest to the bar.","Lower under control."]}'::jsonb, '{"tr":"Barfikse hazırlık; sırt ve duruş için vücut ağırlığıyla çekme hareketi.","en":"Builds toward pull-ups; a bodyweight pull for back and posture."}'::jsonb),
  ('band_pull_apart', 'Lastik Pull Apart', '{"tr":"Lastik Pull Apart","en":"Band Pull-apart"}'::jsonb, 'shoulders', 'band', array['rear_delts', 'upper_back']::text[], '{}'::text[], array['Lastiği omuz hizasında, kollar düz önde tut.', 'Lastiği göğse doğru yanlara aç.', 'Kürek kemiklerini sık.', 'Kontrollü bırak.']::text[], '{"tr":["Lastiği omuz hizasında, kollar düz önde tut.","Lastiği göğse doğru yanlara aç.","Kürek kemiklerini sık.","Kontrollü bırak."],"en":["Hold a band at shoulder height with straight arms.","Pull it apart toward your chest.","Squeeze your shoulder blades.","Return under control."]}'::jsonb, '{"tr":"Omuz ısınması ve duruş için kolay ve etkili.","en":"An easy, effective shoulder warm-up and posture drill."}'::jsonb),
  ('hip_flexor_stretch', 'Kalça Fleksör Esnetme', '{"tr":"Kalça Fleksör Esnetme","en":"Hip Flexor Stretch"}'::jsonb, 'mobility', 'mat', array['hip_flexors']::text[], array['quads']::text[], array['Bir diz yerde, diğer ayak önde yarım diz çökme pozisyonu al.', 'Kalçayı sıkıp hafifçe öne kaydır.', 'Arka bacak kalçasının önünde gerilme hisset.', '30 saniye tut, taraf değiştir.']::text[], '{"tr":["Bir diz yerde, diğer ayak önde yarım diz çökme pozisyonu al.","Kalçayı sıkıp hafifçe öne kaydır.","Arka bacak kalçasının önünde gerilme hisset.","30 saniye tut, taraf değiştir."],"en":["Kneel on one knee with the other foot in front.","Squeeze your glutes and shift your hips slightly forward.","Feel the stretch at the front of the back hip.","Hold 30 seconds, then switch sides."]}'::jsonb, '{"tr":"Uzun süre oturmanın gerdiği kalça önünü açar; bel rahatlığına katkı sağlar.","en":"Opens the front of the hips tightened by sitting; can ease lower-back tension."}'::jsonb),
  ('cat_cow', 'Kedi-İnek', '{"tr":"Kedi-İnek","en":"Cat-Cow"}'::jsonb, 'mobility', 'mat', array['lower_back', 'abs']::text[], '{}'::text[], array['Eller ve dizler üzerinde dur.', 'Nefes alırken beli çukurlaştırıp başı kaldır.', 'Nefes verirken sırtı yukarı yuvarlayıp başı indir.', 'Yavaş tempoda tekrarla.']::text[], '{"tr":["Eller ve dizler üzerinde dur.","Nefes alırken beli çukurlaştırıp başı kaldır.","Nefes verirken sırtı yukarı yuvarlayıp başı indir.","Yavaş tempoda tekrarla."],"en":["Start on hands and knees.","Inhale as you arch your back and lift your head.","Exhale as you round your back and tuck your chin.","Repeat slowly."]}'::jsonb, '{"tr":"Omurga hareketliliğini artırır; ısınma ve soğuma için uygundur.","en":"Improves spinal mobility; good for warm-ups and cool-downs."}'::jsonb),
  ('worlds_greatest_stretch', 'Dünyanın En İyi Esnetmesi', '{"tr":"Dünyanın En İyi Esnetmesi","en":"World''s Greatest Stretch"}'::jsonb, 'mobility', 'mat', array['full_body']::text[], array['hip_flexors', 'hamstrings']::text[], array['Uzun bir lunge pozisyonuna geç, arka diz düz.', 'Öndeki ayağın içine aynı taraftaki dirseği indir.', 'Aynı kolu tavana doğru açarak gövdeyi döndür.', 'Birkaç tekrar sonra taraf değiştir.']::text[], '{"tr":["Uzun bir lunge pozisyonuna geç, arka diz düz.","Öndeki ayağın içine aynı taraftaki dirseği indir.","Aynı kolu tavana doğru açarak gövdeyi döndür.","Birkaç tekrar sonra taraf değiştir."],"en":["Step into a long lunge, back leg straight.","Drop the same-side elbow inside your front foot.","Rotate and reach that arm toward the ceiling.","After a few reps, switch sides."]}'::jsonb, '{"tr":"Kalça, göğüs ve sırt hareketliliğini tek harekette geliştirir.","en":"Improves hip, chest and upper-back mobility in one move."}'::jsonb),
  ('treadmill_walk', 'Koşu Bandında Yürüyüş', '{"tr":"Koşu Bandında Yürüyüş","en":"Treadmill Walk"}'::jsonb, 'cardio', 'machine', array['full_body']::text[], array['calves', 'glutes']::text[], array['Rahat bir tempoyla başla.', 'Hızı ya da eğimi kademeli artır.', 'Dik dur, korkuluklara yüklenme.', 'Son birkaç dakikada tempoyu düşürerek soğu.']::text[], '{"tr":["Rahat bir tempoyla başla.","Hızı ya da eğimi kademeli artır.","Dik dur, korkuluklara yüklenme.","Son birkaç dakikada tempoyu düşürerek soğu."],"en":["Start at an easy pace.","Gradually increase speed or incline.","Stand tall without leaning on the rails.","Slow down for the last few minutes to cool down."]}'::jsonb, '{"tr":"Eklemleri yormadan kalp-damar sağlığını ve günlük enerji harcamasını artırır.","en":"Improves heart health and daily energy expenditure with low joint stress."}'::jsonb),
  ('stationary_bike', 'Sabit Bisiklet', '{"tr":"Sabit Bisiklet","en":"Stationary Bike"}'::jsonb, 'cardio', 'machine', array['quads']::text[], array['glutes', 'calves', 'hamstrings']::text[], array['Seleyi bacak altta neredeyse düz olacak yüksekliğe ayarla.', 'Hafif dirençle 5 dakika ısın.', 'Programdaki süre ve yoğunlukta pedal çevir.', 'Hafif dirençle soğu.']::text[], '{"tr":["Seleyi bacak altta neredeyse düz olacak yüksekliğe ayarla.","Hafif dirençle 5 dakika ısın.","Programdaki süre ve yoğunlukta pedal çevir.","Hafif dirençle soğu."],"en":["Set the saddle so your leg is almost straight at the bottom.","Warm up for 5 minutes at low resistance.","Ride at the time and intensity in your program.","Cool down at low resistance."]}'::jsonb, '{"tr":"Dize az yükle kardiyo; aralıklı antrenman için uygundur.","en":"Knee-friendly cardio; great for intervals."}'::jsonb),
  ('rowing_machine', 'Kürek Makinesi', '{"tr":"Kürek Makinesi","en":"Rowing Machine"}'::jsonb, 'cardio', 'machine', array['full_body']::text[], array['upper_back', 'quads', 'lats']::text[], array['Ayakları sabitle, tutacağı kollar düz şekilde tut.', 'Önce bacaklarla it, sonra gövdeyi hafif geriye yasla.', 'En son kolları karnına çek.', 'Aynı sırayı tersine izleyerek öne dön.']::text[], '{"tr":["Ayakları sabitle, tutacağı kollar düz şekilde tut.","Önce bacaklarla it, sonra gövdeyi hafif geriye yasla.","En son kolları karnına çek.","Aynı sırayı tersine izleyerek öne dön."],"en":["Strap your feet in and hold the handle with straight arms.","Push with your legs first, then lean back slightly.","Finally pull the handle to your stomach.","Return in reverse order."]}'::jsonb, '{"tr":"Tüm vücudu çalıştıran, eklemlere nazik bir kardiyo.","en":"Full-body, joint-friendly cardio."}'::jsonb),
  ('jump_rope', 'İp Atlama', '{"tr":"İp Atlama","en":"Jump Rope"}'::jsonb, 'cardio', 'jump_rope', array['calves', 'full_body']::text[], array['front_delts']::text[], array['İpin saplarını kalça hizasında tut.', 'İpi bileklerle çevir.', 'Ayak uçlarında, alçak ve ritmik sıçra.', 'Dizleri hafif bükük tut.']::text[], '{"tr":["İpin saplarını kalça hizasında tut.","İpi bileklerle çevir.","Ayak uçlarında, alçak ve ritmik sıçra.","Dizleri hafif bükük tut."],"en":["Hold the handles at hip height.","Turn the rope with your wrists.","Jump low and rhythmically on the balls of your feet.","Keep your knees soft."]}'::jsonb, '{"tr":"Koordinasyon, ayak bileği dayanıklılığı ve kondisyon kazandırır.","en":"Builds coordination, ankle resilience and conditioning."}'::jsonb),
  ('cable_crunch', 'Kablo Crunch', '{"tr":"Kablo Crunch","en":"Cable Crunch"}'::jsonb, 'core', 'cable', array['abs']::text[], array['obliques']::text[], array['Yüksek makaraya halat tak, makaraya dönük diz çök.', 'Halatı başının yanında tut.', 'Kalçayı sabit tutarak gövdeyi karnınla aşağı kıvır.', 'Kontrollü dikleş.']::text[], '{"tr":["Yüksek makaraya halat tak, makaraya dönük diz çök.","Halatı başının yanında tut.","Kalçayı sabit tutarak gövdeyi karnınla aşağı kıvır.","Kontrollü dikleş."],"en":["Attach a rope to a high pulley and kneel facing it.","Hold the rope beside your head.","Keep hips still and curl your torso down with your abs.","Rise back up under control."]}'::jsonb, '{"tr":"Karın kaslarını ağırlıkla ve artırılabilir yükle çalıştırır.","en":"Trains the abs with adjustable, progressive load."}'::jsonb),
  ('good_morning', 'Good Morning', '{"tr":"Good Morning","en":"Good Morning"}'::jsonb, 'legs', 'barbell', array['hamstrings', 'lower_back']::text[], array['glutes']::text[], array['Barı squat''taki gibi sırta yerleştir, dizler hafif bükük.', 'Sırtı düz tutarak kalçadan öne eğil.', 'Arka bacakta gerilme hissedince dur.', 'Kalçayı öne iterek dikleş.']::text[], '{"tr":["Barı squat''taki gibi sırta yerleştir, dizler hafif bükük.","Sırtı düz tutarak kalçadan öne eğil.","Arka bacakta gerilme hissedince dur.","Kalçayı öne iterek dikleş."],"en":["Place the bar on your upper back as in a squat, knees soft.","Hinge forward at the hips with a flat back.","Stop when you feel a hamstring stretch.","Drive your hips forward to stand."]}'::jsonb, '{"tr":"Arka bacak ve bel kaslarını güçlendirir; menteşe hareketini pekiştirir.","en":"Strengthens the hamstrings and lower back; reinforces the hip hinge."}'::jsonb),
  ('arnold_press', 'Arnold Press', '{"tr":"Arnold Press","en":"Arnold Press"}'::jsonb, 'shoulders', 'dumbbell', array['front_delts', 'side_delts']::text[], array['triceps']::text[], array['Otur, dambılları avuç içleri sana bakacak şekilde göğüs önünde tut.', 'İterken avuç içlerini öne çevir.', 'Kolları başın üstünde uzat.', 'Dönerek başlangıca indir.']::text[], '{"tr":["Otur, dambılları avuç içleri sana bakacak şekilde göğüs önünde tut.","İterken avuç içlerini öne çevir.","Kolları başın üstünde uzat.","Dönerek başlangıca indir."],"en":["Sit holding dumbbells in front of your chest, palms facing you.","Rotate your palms forward as you press.","Extend your arms overhead.","Rotate back as you lower."]}'::jsonb, '{"tr":"Dönüşlü itme ile omzun ön ve yan kısmını birlikte çalıştırır.","en":"A rotating press that works the front and side delts together."}'::jsonb)
