-- OTOMATİK ÜRETİLDİ: scripts/gen-exercises.mjs (kaynak supabase/data/exercises.json). Elle düzenlemeyin.
-- Sistem hareket kütüphanesi: 62 hareket. Aynı anahtarlı kayıtlar güncellenir.
on conflict (key) where owner_coach_id is null do update set
  name = excluded.name,
  name_i18n = excluded.name_i18n,
  category = excluded.category,
  equipment = excluded.equipment,
  muscles = excluded.muscles,
  secondary_muscles = excluded.secondary_muscles,
  steps = excluded.steps,
  steps_i18n = excluded.steps_i18n,
  benefits_i18n = excluded.benefits_i18n;
